export class GlobError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [index] 0-based index into the pattern where the fault starts
   */
  constructor(message, index) {
    super(message);
    this.name = 'GlobError';
    this.index = index;
  }
}

const PATH_SEPARATOR = 0x2f; // /
const DOT = 0x2e; // .
const STAR = 0x2a; // *
const QUESTION = 0x3f; // ?
const OPEN_BRACKET = 0x5b; // [
const CLOSE_BRACKET = 0x5d; // ]
const BACKSLASH = 0x5c; // \
const DASH = 0x2d; // -

/**
 * Compile a glob pattern into a matcher.
 *
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {(path: string) => boolean} matcher for whole paths
 */
export function compile(pattern, options = {}) {
  if (typeof pattern !== 'string') {
    throw new GlobError('pattern must be a string');
  }
  if (pattern.length === 0) {
    throw new GlobError('pattern must not be empty');
  }

  const dot = options != null && options.dot === true;
  const nocase = options != null && options.nocase === true;
  const patternSegments = splitPattern(pattern);
  const segments = [];

  for (const part of patternSegments) {
    const segment = parseSegment(part.source, part.index, dot, nocase);
    const previous = segments[segments.length - 1];
    if (segment.type === 'globstar' && previous?.type === 'globstar') {
      continue;
    }
    segments.push(segment);
  }

  return function matchPath(path) {
    if (typeof path !== 'string') {
      throw new GlobError('path must be a string');
    }

    return matchSegments(segments, path.split('/'), dot);
  };
}

